   private static boolean isObsolete(String parentTag, String attrName) {
       // Base params always valid
       if (attrName.equals("layout_width") || attrName.equals("layout_height")) return false;
       // Margins are widely supported
       if (attrName.startsWith("layout_margin")) return false;

       String simpleParent = parentTag.contains(".") ? parentTag.substring(parentTag.lastIndexOf('.') + 1) : parentTag;

       switch (simpleParent) {
           case "LinearLayout":
           case "TableRow": // TableRow extends LinearLayout
               return !attrName.equals("layout_weight") && !attrName.equals("layout_gravity");
           case "FrameLayout":
           case "DrawerLayout":
           case "ViewPager":
           case "ViewPager2":
           case "AdapterView":
           case "ListView":
           case "GridView":
           case "RecyclerView":
           case "ScrollView":
           case "HorizontalScrollView":
           case "NestedScrollView":
           case "SwipeRefreshLayout":
           case "FragmentContainerView":
               return !attrName.equals("layout_gravity");
           case "RelativeLayout":
               return !isRelativeLayoutParam(attrName);
           case "ConstraintLayout":
               return !isConstraintLayoutParam(attrName);
           case "GridLayout":
               return !isGridLayoutParam(attrName);
           case "CoordinatorLayout":
               return !isCoordinatorLayoutParam(attrName);
           case "TableLayout":
               // TableLayout children are usually TableRows, but can be other views.
               // It extends LinearLayout, so weight/gravity might apply, but usually not.
               // Let's treat it like LinearLayout for safety.
               return !attrName.equals("layout_weight") && !attrName.equals("layout_gravity");
           case "merge":
           case "include":
               // merge/include don't have layout params themselves in the same way, or they inherit from root.
               return false;
           default:
               // Custom views or unknown layouts: be conservative, don't report.
               return false;
       }
   }
   ```
