   @Override
   public void visitAttribute(@NonNull XmlContext context, @NonNull Attr attribute) {
       String ns = attribute.getNamespaceURI();
       if (!ANDROID_URI.equals(ns)) return;

       String name = attribute.getLocalName();
       if (!name.startsWith("layout_")) return;
       if (name.equals("layout_width") || name.equals("layout_height")) return;
       if (name.startsWith("layout_margin")) return;
       if (name.startsWith("layout_padding")) return; // Not a layout param anyway
       if (name.equals("layout_resource") || name.equals("layout_animation") || name.equals("layout_description")) return;

       Element element = attribute.getOwnerElement();
       Node parentNode = element.getParentNode();
       if (!(parentNode instanceof Element)) return;

       Element parent = (Element) parentNode;
       String parentTag = parent.getTagName();
       if (parentTag.equals("merge") || parentTag.equals("include")) return;

       String simpleParent = getSimpleParentTag(parentTag);
       if (simpleParent == null) return; // Unknown/custom parent

       if (isObsoleteForParent(simpleParent, name)) {
           context.report(ISSUE, attribute, context.getLocation(attribute),
               "Invalid layout param in a `" + simpleParent + "`: `" + name + "`");
       }
   }
